(function(root){
'use strict';
const iso=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(new Date());
const day=s=>Date.parse(s+'T00:00:00Z');
function addMonths(s,n){const d=new Date(day(s)),date=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+n);d.setUTCDate(Math.min(date,new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate()));return d.toISOString().slice(0,10)}
const specs=[['oil','엔진오일 및 오일필터','교체',10000,12,100000,35000,'2026-04-15','oil'],['air','엔진 에어클리너 필터','교체',30000,24,35000,20000,'2025-08-10','filter'],['brake','브레이크 패드 및 디스크','점검',20000,12,250000,26000,'2026-02-10','disc'],['tire','타이어','점검',10000,12,600000,36000,'2026-05-02','tire'],['fluid','브레이크액','교체',40000,24,80000,16000,'2025-04-02','drop'],['cabin','에어컨 필터','교체',15000,12,30000,30000,'2026-03-20','filter'],['wiper','와이퍼','점검',15000,12,40000,34000,'2026-05-02','wiper'],['battery','12V 자동차 배터리','점검',40000,24,180000,15000,'2025-04-02','battery']];
function seed(){return {version:1,vehicle:{model:'그랜저',year:2024,power:'가솔린',odometer:44200},asOf:'2026-11-15',clock:'demo',warningKm:1000,warningDays:30,parts:specs.map(([id,name,kind,km,months,cost,lastKm,lastDate,icon])=>({id,name,kind,km,months,cost,lastKm,lastDate,icon})),records:[{id:'demo-1',partId:'oil',date:'2026-04-15',km:35000,cost:95000,estimate:100000,type:'교체',shop:'시연 정비소',note:'가상 정비 기록'},{id:'demo-2',partId:'cabin',date:'2026-03-20',km:30000,cost:28000,estimate:30000,type:'교체',shop:'시연 정비소',note:'가상 정비 기록'},{id:'demo-3',partId:'tire',date:'2026-05-02',km:36000,cost:20000,estimate:20000,type:'점검',shop:'시연 정비소',note:'타이어 점검 / 가상 기록'}],mileage:[{date:'2026-06-01',km:37500},{date:'2026-07-01',km:39000},{date:'2026-08-01',km:40200},{date:'2026-09-01',km:41800},{date:'2026-10-01',km:43000},{date:'2026-11-15',km:44200}]}}
function active(s){return s.parts.filter(p=>s.vehicle.power!=='전기'||!['oil','air'].includes(p.id))}
function last(s,p){return s.records.filter(r=>r.partId===p.id&&(p.kind==='점검'||r.type==='교체')).sort((a,b)=>b.date.localeCompare(a.date)||b.km-a.km)[0]||{date:p.lastDate,km:p.lastKm}}
function status(s,p){let l=last(s,p),nextKm=p.km?l.km+p.km:null,nextDate=p.months?addMonths(l.date,p.months):null,remainKm=nextKm===null?Infinity:nextKm-s.vehicle.odometer,days=nextDate===null?Infinity:Math.round((day(nextDate)-day(s.asOf))/86400000);let level=remainKm<=0||days<=0?'over':remainKm<=s.warningKm||days<=s.warningDays?'soon':'ok';return {last:l,nextKm,nextDate,remainKm,days,level,label:level==='over'?'기준 도달·초과':level==='soon'?(p.kind==='점검'?'점검 임박':'교체 임박'):'정상',progress:Math.max(0,Math.min(100,Math.max(p.km?(s.vehicle.odometer-l.km)/p.km:0,p.months?(day(s.asOf)-day(l.date))/(day(nextDate)-day(l.date)):0)*100))}}
function plan(s){const end=addMonths(s.asOf,3);return active(s).filter(p=>{const a=status(s,p);return a.remainKm<=10000||(a.nextDate&&a.nextDate<=end)})}
function validateRecord(s,r){if(!s.parts.some(p=>p.id===r.partId))throw Error('소모품을 선택해 주세요.');if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Number.isFinite(day(r.date))||new Date(day(r.date)).toISOString().slice(0,10)!==r.date||r.date>s.asOf)throw Error('정비일은 기준일 이전의 유효한 날짜여야 합니다.');if(!Number.isInteger(r.km)||r.km<0||r.km>s.vehicle.odometer)throw Error('정비 주행거리는 0부터 현재 누적 주행거리 사이로 입력해 주세요.');if(!Number.isFinite(r.cost)||r.cost<0||r.cost>100000000)throw Error('비용은 0~100,000,000원으로 입력해 주세요.');for(const x of s.records.filter(x=>x.id!==r.id)){if((x.date<r.date&&x.km>r.km)||(x.date>r.date&&x.km<r.km))throw Error('날짜와 주행거리가 기존 정비 이력의 순서와 맞지 않습니다.')}return true}
function saveRecord(s,r){validateRecord(s,r);const ix=s.records.findIndex(x=>x.id===r.id);if(ix<0)s.records.push(r);else s.records[ix]=r;return s}
function expense(s,year){const rows=s.records.filter(r=>r.date.startsWith(String(year)));return {total:rows.reduce((a,r)=>a+r.cost,0),estimate:rows.reduce((a,r)=>a+(r.estimate||0),0),months:Array.from({length:12},(_,i)=>rows.filter(r=>+r.date.slice(5,7)===i+1).reduce((a,r)=>a+r.cost,0))}}
const api={iso,day,addMonths,seed,active,last,status,plan,validateRecord,saveRecord,expense};if(typeof module!=='undefined')module.exports=api;else root.PartSaver=api;
})(typeof window!=='undefined'?window:globalThis);
